create temp table _ra(n text, c int) on commit drop;
-- Nhà thầu GPM Hậu Giang: điền mã số thuế, địa chỉ còn trống theo hợp đồng đã ký (người đại diện, tài khoản nhập trên phần mềm)
with t as (update "Organizations" set "TaxCode"=coalesce(nullif("TaxCode",''),'6300287770'), "Address"=coalesce(nullif("Address",''),'Số 363, ấp 3, xã Vị Thanh, huyện Vị Thủy, tỉnh Hậu Giang'), "UpdatedAt"=now() at time zone 'utc', "UpdatedBy"='Quản trị hệ thống' where "Id"='dk-nt-1e86f48733e9dc13' and (coalesce("TaxCode",'')='' or coalesce("Address",'')='') returning 1) insert into _ra select 'nha thau GPM bo sung', count(*) from t;
-- DA051-TV07: nhà thầu theo hợp đồng đã ký
with t as (update "Packages" set "ContractorIds"='["dk-nt-1e86f48733e9dc13"]', "JointVenture"=null, "ContractorShares"='{}', "UpdatedAt"=now() at time zone 'utc', "UpdatedBy"='Quản trị hệ thống' where "Id"=(select "PackageId" from "Contracts" where "Id"='dk-hd-092812768dda243f') and coalesce("ContractorIds",'')<>'["dk-nt-1e86f48733e9dc13"]' returning 1) insert into _ra select 'goi thau doi nha thau', count(*) from t;
with t as (update "Contracts" set "Contractor"='Công ty TNHH Xây dựng GPM Hậu Giang', "UpdatedAt"=now() at time zone 'utc', "UpdatedBy"='Quản trị hệ thống' where "Id"='dk-hd-092812768dda243f' and coalesce("Contractor",'')<>'Công ty TNHH Xây dựng GPM Hậu Giang' returning 1) insert into _ra select 'hop dong doi nha thau', count(*) from t;

