insert into "AuditLogs"("Id","Ts","Username","Fullname","Action","Module","Target","UpdatedAt","UpdatedBy")
select 'shd-'||left(md5(random()::text),16), now() at time zone 'utc', 'admin', 'Quản trị hệ thống', 'Cập nhật dữ liệu', 'Quản trị hệ thống',
  'Số hợp đồng từ tệp: '||string_agg(n||' '||c, '; '), now() at time zone 'utc', 'Quản trị hệ thống'
from (select n, sum(c) c from _ra group by n) x where c>0 having count(*)>0;
select n, sum(c) from _ra group by n order by n;
select 'hop dong con so tam', count(*) from "Contracts" where "Number" like 'HĐ-DA%';
select 'hop dong chua co so', count(*) from "Contracts" where coalesce("Number",'')='';
select 'hop dong chua ngay ky', count(*) from "Contracts" where "SignDate" is null;
select 'hop dong bat dau truoc ngay ky', count(*) from "Contracts" where "Start"<"SignDate";
commit;
